// src/commands/acculynx_get_job_production_schedule.ts
var acculynx_get_job_production_schedule_default = defineAcculynxTool({
  description: "Extract production schedule assignments, work order references, and scheduled start/end dates for a job by inspecting its event history log.",
  inputSchema: external_exports.object({
    jobId: external_exports.string().guid().describe("Unique UUID string identifying the target job"),
    response_format: external_exports.nativeEnum(ResponseFormat).optional().describe("Output serialization format")
  }),
  async call(client2, { jobId }) {
    const MAX_HISTORY_EVENTS = 50;
    const PAGE_SIZE3 = 25;
    const items = [];
    let recordStartIndex = 0;
    while (items.length < MAX_HISTORY_EVENTS) {
      const res = await client2.getJobHistory({ jobId, pageSize: PAGE_SIZE3, recordStartIndex });
      const pageItems = res.data?.items || [];
      if (pageItems.length === 0) break;
      items.push(...pageItems);
      recordStartIndex += pageItems.length;
      if (items.length >= MAX_HISTORY_EVENTS) break;
    }
    const scheduleEvents = items.filter((item) => {
      const text = (item?.action || "").toLowerCase();
      return text.includes("start date") || text.includes("end date") || text.includes("assignment changed") || text.includes("order saved");
    });
    const outputData = {
      jobId,
      productionScheduleFound: scheduleEvents.length > 0,
      extractedScheduleEvents: scheduleEvents,
      recentHistoryContext: items.slice(0, 10)
      // provide baseline context
    };
    return outputData;
  }
});

